-- 981 — Karolinska Institutet Global Master's Scholarship --------------------------------------
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (981, 'Karolinska Institutet Global Master''s Scholarship', 'Karolinska Institutet', 'Sweden', 'Full Tuition Waiver', 0, 'For autumn 2027 entry the scholarship application period runs 8-24 February 2027, with results published 26 April 2027 and a 30 April 2027 deadline to accept. The scholarship application is a separate process from the programme application: first apply for a KI global master''s programme at universityadmissions.se (you must rank a KI programme as your first choice), then apply directly to Karolinska Institutet for the scholarship during the February window - the application link is published on the scholarship page when the period opens.', '2027-02-24', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["Karolinska Institutet's global (English-taught) master's programmes in medicine and life science - EXCEPT the two Stockholm Trio joint programmes, Master's in Molecular Techniques in Life Science and Master's in Biostatistics and Data Science, which are funded through the Stockholm Trio Scholarship instead (record 982)"]$j$, $j$["Students who are required to pay tuition fees throughout their studies (fee liability under Swedish rules - in practice citizens from outside the EU/EEA and Switzerland without an exemption), who applied to a KI master's programme and ranked a KI programme as their first choice"]$j$, NULL, NULL, false, true, $desc$The KI Global Master's Scholarship is Karolinska Institutet's merit scholarship for fee-paying master's students: around ten to twelve scholarships a year (12 awardees in 2026, 10 in 2025) spread across KI's global master's programmes, each covering the tuition fees in full. Be clear-eyed about the boundary: the scholarship only covers tuition fees - living expenses, accommodation and travel are yours to fund, and Stockholm living costs are substantial, so the university itself warns you to make sure you can support yourself. It is also ferociously competitive: 1,002 students applied for the scholarship in the 2026 cycle (687 in 2025) against 484 fee-paying students admitted to KI master's programmes that year, for roughly a dozen awards. Selection is mechanical in a good way: awards are based on your merit rating from the KI CV form, assessed by academic staff at each programme - the scholarship applicant with the highest merit rating in each programme is offered the scholarship (a lottery breaks exact ties, and a declined offer passes to the second-best rating). The route in has a strict shape: you must have applied for a KI master's programme through universityadmissions.se and ranked a KI programme as your first choice (you remain eligible if you are admitted to a lower-ranked KI option), you must be a tuition fee-paying student throughout your studies, and you then submit a separate scholarship application directly to KI during the February window (8-24 February 2027 for autumn 2027 entry); only admitted students are considered in the final selection, results come on 26 April 2027 and offers must be accepted by 30 April 2027. Two programmes sit outside this scheme entirely - the joint Master's in Molecular Techniques in Life Science and Biostatistics and Data Science are funded via the Stockholm Trio Scholarship (record 982) - and KI offers no scholarships at bachelor's level or for non-fee-paying students.$desc$, $req$Three eligibility conditions are stated on the scholarship page: you are a tuition fee-paying student throughout your studies (check your fee status on universityadmissions.se), you have applied for a master's programme at Karolinska Institutet, and you ranked a KI programme as your first choice - ranking matters, although you stay eligible if you end up admitted to a lower-ranked KI option. The process then runs: (1) apply for one of KI's global master's programmes at universityadmissions.se, following the CV-form instructions carefully because the scholarship is decided on your CV-form merit rating; (2) apply for the scholarship separately, directly to KI, during the scholarship application period (8-24 February 2027 for the coming cycle; the link is published on the scholarship page when the window opens) - programme academic staff assess the CV forms, the highest-rated applicant per programme is offered the award, ties go to a lottery and declines pass the offer down; (3) results are published 26 April 2027 with email notification; (4) accept via the acceptance form in the notification email by 30 April 2027. Only admitted students are considered in the final selection, and the two Stockholm Trio joint programmes (Molecular Techniques in Life Science; Biostatistics and Data Science) are NOT eligible for this scholarship - their applicants use the Stockholm Trio Scholarship (record 982) through KTH. Budget honestly: the award covers tuition only, so living costs, housing and travel need separate funding. English-language requirements belong to programme admission, and no scheme-level GPA or IELTS cutoff is published, so min_gpa/min_ielts are not recorded.$req$, 'https://education.ki.se/bachelors-masters-studies/scholarships/the-ki-global-masters-scholarships-for-fee-paying-students', 'https://education.ki.se/bachelors-masters-studies/scholarships/the-ki-global-masters-scholarships-for-fee-paying-students', 'https://education.ki.se/bachelors-masters-studies/scholarships/the-ki-global-masters-scholarships-for-fee-paying-students', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 23) from Karolinska Institutet's official pages fetched the same day: the 'Apply for the KI Global Master's Scholarship' page (scholarship application timeline for the coming cycle - 8 to 24 February 2027 application period, results 26 April 2027, accept by 30 April 2027; eligibility: tuition fee-paying throughout the studies, applied for a KI master's programme, ranked a KI programme first choice, remaining eligible if admitted to a lower-ranked KI option; covers tuition fees only - living expenses, accommodation and travel excluded; assessment on the merit rating from the KI CV form by programme academic staff, highest-rated applicant per programme offered the scholarship, lottery on equal ratings, offer passes to second-best on decline; statistics table: 2026 - 1002 applicants, 12 awardees; 2025 - 687 applicants, 10 awardees; 484 fee-paying students admitted in 2026; the two joint programmes Molecular Techniques in Life Science and Biostatistics and Data Science explicitly NOT eligible, with a pointer to KTH scholarship opportunities; separate application to KI with the link published when the window opens; only admitted students considered in the final selection; acceptance via form in the notification email) and the 'Scholarships for prospective master's students' overview (around 10 scholarships per year distributed across all global master's programmes, high competition with approximately 700 international applicants annually; KI offers no scholarships for bachelor's-level studies or for EU citizens / non-fee-paying students; the sibling KI-DIS Fellowship - a co-funded merit scholarship covering tuition for any KI global master's, available annually to ONE alumnus of DIS study-abroad semesters in Stockholm or Copenhagen - is deliberately not given its own record in this batch because of its single-award alumni-only scope). Deadline 2027-02-24 ('fixed') is the published close of the scholarship window; status 'upcoming' because the form opens 8 February 2027. Award stored as NULL (SEK, 'year', 'variable') aligned with the KTH Scholarship record 325 - full tuition varies by programme; amount_usd_value 0 (non-USD). university_id NULL and NO university_scholarships row: no university record for Karolinska Institutet exists yet (verified by query; creating it is a future backlink task). Dedupe at time of adding: no prior Karolinska record existed (the earlier 'Stockholm Trio' candidate note resolves to records 981 and 982; KTH 325/968/969 and Stockholm University 673 were already in the catalogue). Linked source: 3114.$note$, NULL, NULL, 'SEK', 'year', 'variable', NULL, 'Full tuition-fee scholarship (tuition only - living costs, accommodation and travel are not covered); around 10-12 awards per year distributed across KI''s global master''s programmes, decided on the KI CV-form merit rating', 'Covers the tuition fees in full for the master''s programme; every other cost (living expenses, accommodation, travel) must be self-funded.', 'No scholarship-specific IELTS figure; English-language requirements belong to master''s programme admission via universityadmissions.se.', $j$["Master's programme application at universityadmissions.se with a KI programme ranked as first choice", "KI CV form completed per the published instructions (the scholarship is awarded on the CV-form merit rating assessed by programme academic staff)", "Separate scholarship application submitted directly to Karolinska Institutet during the scholarship window (8-24 February 2027 for autumn 2027 entry)", "If offered: acceptance form in the notification email submitted by 30 April 2027"]$j$, NULL, NULL, $json$[{"cycle": "Autumn 2027 entry", "scholarship_application_opens": "2027-02-08", "deadline": "2027-02-24", "results": "2027-04-26", "accept_by": "2027-04-30", "status": "upcoming"}, {"pattern": "Annual: apply to a KI global master's in the international admission round with KI ranked first choice, then apply for the scholarship directly to KI in February; results in late April"}]$json$);

-- 982 — Stockholm Trio Scholarship ----------------------------------------------------------------
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (982, 'Stockholm Trio Scholarship', 'Karolinska Institutet, KTH Royal Institute of Technology and Stockholm University (Stockholm Trio)', 'Sweden', 'Full Tuition Waiver', 0, 'Applications run through the KTH Scholarship application: for autumn 2027 entry the form opens 1 December 2026 and closes 15 January 2027, with results announced 1 April 2027. You must first have applied for one of the two joint master''s programmes via universityadmissions.se as your first priority (and paid the application fee); no additional documents are needed for the scholarship application, but your University Admissions documents must be in by 1 February.', '2027-01-15', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["The two joint master's programmes of the Stockholm Trio alliance only: Master's Programme in Molecular Techniques in Life Science and Master's Programme in Biostatistics and Data Science (jointly run by Karolinska Institutet, KTH Royal Institute of Technology and Stockholm University)"]$j$, $j$["Tuition fee-paying students admitted to one of the two Stockholm Trio joint master's programmes"]$j$, NULL, NULL, false, true, $desc$The Stockholm Trio Scholarship is the jointly funded tuition scholarship of the Stockholm Trio university alliance - Karolinska Institutet, KTH Royal Institute of Technology and Stockholm University - created for the alliance's two joint master's programmes: Molecular Techniques in Life Science and Biostatistics and Data Science. It covers the full tuition fee for the two-year programme (living costs are not included), and KTH's programme pages spell out the funding plainly: 'The scholarship is funded jointly by KTH, Karolinska Institutet and Stockholm University.' The practical routing needs care, because three similar-sounding doors exist and only one is right: applicants to these two programmes apply for funding through the KTH Scholarship application on KTH's website (Stockholm University's scholarship page sends you there too, and Karolinska's cohort reporting names the award the 'KI-KTH-SU Scholarship'); they are explicitly not eligible for the KI Global Master's Scholarship (record 981 excludes exactly these programmes) nor for the KTH Joint Programme Scholarship (record 969 excludes them and points here). Administration follows the KTH Scholarship's rules: you must be a fee-paying student who applied for the programme as your first priority on universityadmissions.se and paid the application fee; the scholarship form itself needs no extra documents (your University Admissions documents, due 1 February, are reused); and selection is made primarily on academic excellence - grades, the ranking of the university that awarded your bachelor's degree, research/work/teaching experience and competition awards, and your motivation for contributing to the sustainable development goals. Under the KTH Scholarship's published content, the tuition is covered for the first and the second year provided first-year results are satisfactory.$desc$, $req$Eligibility is programme-bound: fee-paying students admitted to either the Master's Programme in Molecular Techniques in Life Science or the Master's Programme in Biostatistics and Data Science - no other programmes qualify, whichever of the three universities you think of as 'yours'. The sequence is: (1) apply for the joint programme via universityadmissions.se, as your first priority, and pay the application fee (KTH Scholarship rules make first-priority status and fee payment conditions of eligibility, and you cannot be awarded a scholarship for a second-, third- or fourth-priority programme); (2) when the KTH Scholarship application opens (1 December 2026 for autumn 2027), submit the scholarship form on the KTH Scholarship page by 15 January 2027 - no additional documents are required for the scholarship itself, but the documents in your University Admissions application are reused for evaluation and must be submitted by 1 February; (3) selection runs in parallel with admissions and is based primarily on academic excellence (grades/GPA, ranking of your bachelor's-degree university, extracurricular research or publications, relevant work/teaching experience, competition awards, and your stated motivation for contributing to the sustainable development goals with this degree); (4) results are announced 1 April 2027. Do not use the neighbouring schemes for these programmes: the KI Global Master's Scholarship (record 981) expressly excludes both joint programmes, and the KTH Joint Programme Scholarship (record 969) excludes them in favour of this route. The award covers tuition only, so Stockholm living costs need separate funding. No scheme-level GPA or IELTS cutoff is published (selection weighs grades as part of the whole file), so min_gpa/min_ielts are not recorded.$req$, 'https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships', 'https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-scholarship-1.72827', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 23) from official pages fetched the same day: Stockholm University's Scholarships page ('Stockholm Trio Scholarship' section - fee-paying students admitted to a joint master's programme within the Stockholm Trio alliance can apply; covers the full tuition fee; eligible programmes are the Master's in Molecular Techniques in Life Science and the Master's in Biostatistics and Data Science; the alliance is the partnership between Karolinska Institutet, KTH and Stockholm University; application via the KTH Scholarship page), the KTH Scholarship page (full tuition fee of a one- or two-year master's programme, second year conditional on satisfactory first-year results, no living costs; eligible programmes expressly include the joint master's in Molecular Techniques in Life Science and Biostatistics and Data Science; eligibility requires fee-paying status, a KTH programme as first priority and the application fee paid; no additional documents for the scholarship form, University Admissions documents due 1 February; selection criteria: grades, bachelor's-university ranking, research/work/teaching experience and awards, sustainable-development motivation; the same page's published cycle for autumn 2027 - form opens 1 December 2026, closes 15 January 2027, results 1 April 2027 - is the date set recorded here and matches catalogue record 325), KTH's 'Fees and scholarships for Biostatistics and Data Science' page (fee-paying applicants to the joint programme can apply for the KTH Scholarship covering tuition for two years; 'The scholarship is funded jointly by KTH, Karolinska Institutet and Stockholm University'), and Karolinska's Global Master's Scholarship page (both joint programmes excluded from KI's own scholarship with a pointer to KTH - see record 981). Karolinska's award reporting names this the 'KI-KTH-SU Scholarship'. deadline_date 2027-01-15 ('fixed'), status 'upcoming' (form opens 1 December 2026), mirroring record 325. Award stored as NULL (SEK, 'year', 'variable') aligned with 325; amount_usd_value 0. university_id NULL and no university_scholarships rows BY DESIGN: the scholarship belongs to a three-university alliance (Karolinska has no university record yet; attributing it to KTH or SU alone would misstate the funder), though the application is hosted by KTH (application_url). This record is the long-standing 'Stockholm Trio' enrichment candidate. Linked sources: 2623 (SU Scholarships page, shared) and 2557 (KTH Scholarship page, shared with record 325).$note$, NULL, NULL, 'SEK', 'year', 'variable', NULL, 'Full tuition fee for the two Stockholm Trio joint master''s programmes (Molecular Techniques in Life Science; Biostatistics and Data Science), funded jointly by Karolinska Institutet, KTH and Stockholm University; applied for through the KTH Scholarship application; living costs not covered', 'Covers the tuition fee for the two-year joint programme (under KTH Scholarship terms, the second year provided first-year results are satisfactory); no living-cost support.', 'No scholarship-specific IELTS figure; English-language requirements belong to programme admission via universityadmissions.se.', $j$["Application to the Master's in Molecular Techniques in Life Science or the Master's in Biostatistics and Data Science via universityadmissions.se, ranked as first priority, with the application fee paid", "KTH Scholarship application form submitted on the KTH Scholarship page during the window (1 December 2026 - 15 January 2027 for autumn 2027); no additional scholarship documents - University Admissions documents are reused and must be submitted by 1 February", "Motivation statement within the scholarship assessment on how you will contribute to the sustainable development goals with the degree"]$j$, NULL, NULL, $json$[{"cycle": "Autumn 2027 entry (via the KTH Scholarship application)", "opens": "2026-12-01", "deadline": "2027-01-15", "results": "2027-04-01", "status": "upcoming"}, {"pattern": "Annual with the KTH Scholarship round; applicants to the two Trio joint programmes are routed here instead of the KI Global Master's Scholarship or the KTH Joint Programme Scholarship"}]$json$);

-- 983 — Vinge Stockholm Arbitration Scholarship (SAS) -------------------------------------------------
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (983, 'Vinge Stockholm Arbitration Scholarship (SAS)', 'Stockholm University', 'Sweden', 'Full Tuition Waiver', 0, 'No fixed scholarship deadline is published. The ICAL LL.M. has one application round per year (applications open mid-October, deadline mid-January, for an autumn start); when the scholarship is available, its application round opens after the admission results are sent out, and the relevant (admitted) students are advised of the application process at that point. Secure admission to the programme first - the scholarship round only concerns admitted students.', NULL, 'not_published', NULL, NULL, $j$["Master's"]$j$, $j$["Only the Master of Laws (LL.M.) (60 credits) in International Commercial Arbitration Law (ICAL) at Stockholm University's Department of Law"]$j$, $j$["Students with citizenship outside the EU/EEA who are specifically admitted to the ICAL LL.M. and must pay tuition"]$j$, NULL, NULL, false, true, $desc$The Stockholm Arbitration Scholarship - on the programme's own page, the 'Vinge Stockholm Arbitration Scholarship', after its sponsor - is one of the two arbitration-law scholarships usually available each year for students specifically admitted to Stockholm University's LL.M. in International Commercial Arbitration Law (ICAL). It covers the cost of tuition for the one-year, 60-credit programme (no living-cost component is published), and exists precisely because tuition is charged to students with citizenship outside the EU/EEA. The ICAL context is the point of the money: the LL.M. has run for more than 20 years with graduates from over 80 countries, is structured around a full mock arbitration (from filing submissions to issuing an arbitral award) plus a master thesis, and sits in a city internationally recognised as a seat of arbitration and home to the SCC Arbitration Institute. Timing is sequential and admission-led: the programme has a single application round each year (mid-October to mid-January for an autumn start), and when the scholarship is available its own application round opens only after the admission results are sent out - admitted students are then advised of the process, so there is no standalone early application to prepare. You may apply for several scholarships in parallel (the Stockholm University Scholarship Scheme, record 673, and the Swedish Institute scholarships, record 922, are named on the programme page), but you can only be granted one. Its sibling award, the Swedish Arbitration Association (SAA) Scholarship, is record 984.$desc$, $req$Everything runs through ICAL admission. Programme eligibility: an undergraduate degree in law from an internationally recognised university (or equivalent with a minimum of 180 ECTS in law; final-year students may apply) and English proficiency equivalent to English 6 in the Swedish upper-secondary system, evidenced via University Admissions. Apply through universityadmissions.se in the programme's only round (opens mid-October, deadline mid-January, autumn start) with the programme's own selection documents in English: a personal statement on the programme template, two letters of recommendation (maximum one A4 page each, signed, with contact information, preferably on official letterhead), and a CV of maximum two A4 pages - selection among eligible applicants weights law-study grades and relevant extracurricular/professional experience most heavily, then the statement and recommendations. The scholarship itself then works as follows (programme page): two scholarships, this Vinge-sponsored Stockholm Arbitration Scholarship and the SAA Scholarship (record 984), are usually available for students specifically admitted to the LL.M.; they cover the cost of tuition and are aimed at students with citizenship outside the EU/EEA; when available, the application round opens after the admission results are sent out and the relevant students are advised of the process then - so admitted students should watch for the post-results instructions rather than any public deadline. You may apply for several scholarships (including the Stockholm University Scholarship Scheme and Swedish Institute scholarships) but can only be granted one. No numeric GPA cutoff or IELTS figure is published for the scholarship (the English 6 equivalence belongs to admission), so min_gpa/min_ielts are not recorded.$req$, 'https://www.su.se/english/education/course-catalogue/ji/jic1m', 'https://www.su.se/english/education/course-catalogue/ji/jic1m', 'https://www.su.se/english/education/course-catalogue/ji/jic1m', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 23) from Stockholm University official pages fetched the same day: the ICAL programme page (Master of Laws (LL.M.) (60 credits) in International Commercial Arbitration - 'Two scholarships are usually available for students specifically admitted to the LL.M. in International Commercial Arbitration Law. These are the Vinge Stockholm Arbitration Scholarship and the Swedish Arbitration Association (SAA) Scholarship. These scholarships cover the cost of tuition and are therefore a funding opportunity for students with citizenships outside the EU/EEA. When available, the application round for these scholarship opens after the admission results are sent out. The relevant students will be advised of the application process after the admission results are published'; applicants may apply for several scholarships including the Stockholm University scheme and Swedish Institute but can only be granted one; programme facts: one application round per year opening mid-October with a mid-January deadline for autumn commencement, all applications via University Admissions, entry requires a law degree of at least 180 ECTS (final-year applicants allowed) and English equivalent to English 6, selection weighted on law grades and relevant experience then personal statement and two recommendation letters, documents = personal statement on the programme template, two signed one-page LORs with contact details, CV max two pages; mock arbitration and master thesis; 20+ years, graduates from 80+ countries; contacts master@juridicum.su.se / ICAL@juridicum.su.se) and the central Scholarships page ('Scholarships in Arbitration Law' section names the Stockholm Arbitration Scholarship (SAS) and the SAA Scholarship, covering the cost of tuition for citizenships outside the EU/EEA, and points to the programme page for details). Title combines both official namings. Sponsor Vinge is named in the funding text; provider recorded as Stockholm University (the admitting institution whose pages carry the award). deadline_date NULL/'not_published' with status 'upcoming': the scholarship round opens after admission results and no date is published. Award NULL (SEK, 'year', 'variable') aligned with record 325 - the pages say only that the scholarship covers 'the cost of tuition' and no ICAL-specific fee figure is stated on them, so none is recorded; amount_usd_value 0. university_id 140 (Stockholm University); university_scholarships row 706 created. This and the SAA Scholarship (record 984) are the long-standing 'Stockholm University ICAL SAS/SAA' enrichment candidates. Linked sources: 3115 (programme page) and 2623 (central Scholarships page, shared).$note$, 140, NULL, 'SEK', 'year', 'variable', NULL, 'Covers the cost of tuition for the one-year ICAL LL.M.; the Stockholm Arbitration Scholarship (SAS), sponsored by Vinge; one of two arbitration-law scholarships usually available each year (application round opens after admission results)', 'Pays the tuition cost of the LL.M. in International Commercial Arbitration Law; no living-cost component is published on the pages read.', 'Programme entry requires English proficiency equivalent to English 6 (Swedish upper-secondary level), evidenced through University Admissions; no scholarship-specific IELTS figure.', $j$["Admission to the LL.M. in International Commercial Arbitration Law via University Admissions (law degree of at least 180 ECTS, or final-year standing; English 6 equivalence)", "Programme selection documents in English: personal statement on the programme template, two signed recommendation letters (max one A4 page each, with contact information), CV (max two A4 pages)", "Scholarship application after admission results are published, following the process advised to admitted students when the round opens"]$j$, NULL, NULL, $json$[{"pattern": "Annual with ICAL's single admission round (programme applications mid-October to mid-January for autumn entry); the scholarship application round, when available, opens after admission results are sent out and admitted students are advised of the process"}]$json$);

-- 984 — Swedish Arbitration Association (SAA) Scholarship -------------------------------------------------
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (984, 'Swedish Arbitration Association (SAA) Scholarship', 'Stockholm University', 'Sweden', 'Full Tuition Waiver', 0, 'No fixed scholarship deadline is published. The ICAL LL.M. has one application round per year (applications open mid-October, deadline mid-January, for an autumn start); when the scholarship is available, its application round opens after the admission results are sent out, and the relevant (admitted) students are advised of the application process at that point. Secure admission to the programme first - the scholarship round only concerns admitted students.', NULL, 'not_published', NULL, NULL, $j$["Master's"]$j$, $j$["Only the Master of Laws (LL.M.) (60 credits) in International Commercial Arbitration Law (ICAL) at Stockholm University's Department of Law"]$j$, $j$["Students with citizenship outside the EU/EEA who are specifically admitted to the ICAL LL.M. and must pay tuition"]$j$, NULL, NULL, false, true, $desc$The Swedish Arbitration Association (SAA) Scholarship is one of the two arbitration-law scholarships usually available each year for students specifically admitted to Stockholm University's LL.M. in International Commercial Arbitration Law (ICAL), named for its sponsor, the Swedish Arbitration Association. It covers the cost of tuition for the one-year, 60-credit LL.M. (no living-cost component is published) and exists as a funding opportunity for students with citizenship outside the EU/EEA, who are the ones charged tuition. The programme it attaches to is purpose-built for arbitration careers: running for more than 20 years with graduates from over 80 countries, built around an end-to-end mock arbitration (filing submissions, collecting evidence, cross-examining witnesses, pleading at a hearing, issuing an arbitral award) and a master thesis, in the city that hosts the SCC Arbitration Institute. The funding sequence runs behind admission: ICAL has a single application round per year (mid-October to mid-January for an autumn start), and when this scholarship is available, its application round opens after the admission results are sent out, with the relevant students advised of the process then - there is no earlier standalone application. ICAL applicants may apply for several scholarships (the programme page names the Stockholm University Scholarship Scheme, record 673, and the Swedish Institute scholarships, record 922) but can only be granted one. Its sibling award, the Vinge Stockholm Arbitration Scholarship (SAS), is record 983.$desc$, $req$Start with admission, because the scholarship only opens to those specifically admitted to the LL.M. Programme eligibility: an undergraduate degree in law from an internationally recognised university (or equivalent with at least 180 ECTS in law; students in the last year of such a degree can apply) plus English proficiency equivalent to English 6 in the Swedish upper-secondary system. Apply via University Admissions in the annual round (mid-October to mid-January, autumn start) and add the programme's selection documents in English - a personal statement using the programme template, two letters of recommendation of at most one A4 page each (signed, with contact information, preferably on letterhead), and a CV of at most two A4 pages; eligible applicants are selected on a weighted assessment in which grades from earlier legal studies and relevant extracurricular/professional experience carry most weight, with the personal statement and recommendation letters behind them. For the scholarship itself, the university's published terms (programme page, echoed on the central Scholarships page) are that the SAA Scholarship and the Vinge Stockholm Arbitration Scholarship (record 983) are usually available to ICAL admits, cover the cost of tuition, and target citizens from outside the EU/EEA; when available, the application round opens after admission results are sent out and relevant students are advised of the application process after results are published - so watch your post-admission messages instead of a public deadline. You are allowed to apply for several scholarships (Stockholm University Scholarship Scheme, Swedish Institute) but can only be granted one. No numeric GPA or IELTS threshold is published for the award (English 6 is an admission requirement), so min_gpa/min_ielts are not recorded.$req$, 'https://www.su.se/english/education/course-catalogue/ji/jic1m', 'https://www.su.se/english/education/course-catalogue/ji/jic1m', 'https://www.su.se/english/education/course-catalogue/ji/jic1m', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 23) from Stockholm University official pages fetched the same day: the ICAL programme page (LL.M. (60 credits) in International Commercial Arbitration - the Vinge Stockholm Arbitration Scholarship and the Swedish Arbitration Association (SAA) Scholarship are 'usually available for students specifically admitted to the LL.M. in International Commercial Arbitration Law', cover the cost of tuition for students with citizenships outside the EU/EEA, and 'when available, the application round for these scholarship opens after the admission results are sent out', with relevant students advised of the process after results are published; ICAL applicants may apply for several scholarships (SU scheme and Swedish Institute named) but can only be granted one; one admission round per year, mid-October to mid-January for autumn start, via University Admissions; entry: law degree with at least 180 ECTS or final-year standing, English 6 equivalence; weighted selection led by law grades and relevant experience; documents: templated personal statement, two signed one-page LORs, two-page CV; mock arbitration plus thesis; contacts master@juridicum.su.se / ICAL@juridicum.su.se) and the central Scholarships page ('Scholarships in Arbitration Law': the Stockholm Arbitration Scholarship (SAS) and the Swedish Arbitration Association (SAA) Scholarship cover the cost of the tuition for citizenships outside the EU/EEA). Sponsor (Swedish Arbitration Association) is the award's name and is recorded in the funding text; provider recorded as Stockholm University, whose pages carry the award. deadline_date NULL/'not_published' with status 'upcoming' (round opens after admission results; no date published). Award NULL (SEK, 'year', 'variable') aligned with record 325 - no ICAL-specific fee figure appears on the pages read, so none is recorded; amount_usd_value 0. university_id 140 (Stockholm University); university_scholarships row 707 created. Sibling: Vinge Stockholm Arbitration Scholarship (SAS), record 983 - together they are the long-standing 'Stockholm University ICAL SAS/SAA' enrichment candidates. Linked sources: 3115 (programme page) and 2623 (central Scholarships page, shared).$note$, 140, NULL, 'SEK', 'year', 'variable', NULL, 'Covers the cost of tuition for the one-year ICAL LL.M.; sponsored by the Swedish Arbitration Association (SAA); one of two arbitration-law scholarships usually available each year (application round opens after admission results)', 'Pays the tuition cost of the LL.M. in International Commercial Arbitration Law; no living-cost component is published on the pages read.', 'Programme entry requires English proficiency equivalent to English 6 (Swedish upper-secondary level), evidenced through University Admissions; no scholarship-specific IELTS figure.', $j$["Admission to the LL.M. in International Commercial Arbitration Law via University Admissions (law degree of at least 180 ECTS, or final-year standing; English 6 equivalence)", "Programme selection documents in English: personal statement on the programme template, two signed recommendation letters (max one A4 page each, with contact information), CV (max two A4 pages)", "Scholarship application after admission results are published, following the process advised to admitted students when the round opens"]$j$, NULL, NULL, $json$[{"pattern": "Annual with ICAL's single admission round (programme applications mid-October to mid-January for autumn entry); the scholarship application round, when available, opens after admission results are sent out and admitted students are advised of the process"}]$json$);

